import parseUrl from 'url-parse'

import axios from '@nextcloud/axios'
import { generateRemoteUrl } from '@nextcloud/router'

const encodeString = function(data) {
	if (typeof TextEncoder !== 'undefined') {
		return new TextEncoder().encode(data).buffer
	}

	const buffer = new ArrayBuffer(data.length)
	const view = new Uint8Array(buffer)
	for (let i = 0; i < data.length; i++) {
		view[i] = data.charCodeAt(i)
	}
	return buffer
}

const getDataLength = function(data) {
	if (typeof data === 'string') {
		return encodeString(data).byteLength
	}
	if (data instanceof ArrayBuffer) {
		return data.byteLength
	}
	if (data?.byteLength !== undefined) {
		return data.byteLength
	}
	if (data?.size !== undefined) {
		return data.size
	}
	return undefined
}

// init webdav client on default dav endpoint
const remote = generateRemoteUrl('dav')
const remoteBase = remote.replace(/\/$/, '')

const encodePath = function(path) {
	return path.split('/').map(encodeURIComponent).join('/')
}

const getUrl = function(path) {
	return remoteBase + encodePath(path.startsWith('/') ? path : '/' + path)
}

const getErrorStatus = function(error) {
	return error?.response?.status ?? error?.status
}

const client = {
	async createDirectory(path, options = {}) {
		const url = getUrl(path).replace(/\/?$/, '/')
		await axios({
			...options,
			method: 'MKCOL',
			url,
		})
	},

	async customRequest(path, options) {
		return axios({
			...options,
			url: options.url || getUrl(path),
		})
	},

	async exists(path) {
		try {
			await axios({
				headers: {
					Accept: 'text/plain,application/xml',
					Depth: '0',
				},
				method: 'PROPFIND',
				url: getUrl(path),
			})
		} catch (error) {
			if (getErrorStatus(error) === 404) {
				return false
			}
			throw error
		}

		return true
	},

	async putFileContents(filename, data, options = {}) {
		const {
			contentLength = true,
			headers = {},
			overwrite = true,
			onUploadProgress,
			signal,
		} = options

		const requestHeaders = {
			'Content-Type': 'application/octet-stream',
			...headers,
		}
		const dataLength = contentLength === true ? getDataLength(data) : contentLength
		if (typeof dataLength === 'number') {
			requestHeaders['Content-Length'] = dataLength.toString()
		}
		if (overwrite === false) {
			requestHeaders['If-None-Match'] = '*'
		}

		try {
			await axios({
				data,
				headers: requestHeaders,
				method: 'PUT',
				onUploadProgress,
				signal,
				url: getUrl(filename),
			})
		} catch (error) {
			if (getErrorStatus(error) === 412 && overwrite === false) {
				return false
			}
			throw error
		}

		return true
	},
}

export const remotePath = parseUrl(remote).pathname
export default client

